"""Runtime support for vecDSL programs generated for Chroma with the chromadb-client SDK. Generated by vecDSL 7. Do not edit."""

from __future__ import annotations

import json
import math
import os
import random
import re
from importlib.metadata import PackageNotFoundError, version
from typing import Any, Iterator, NoReturn, Sequence
from urllib.parse import urlparse

SDK_PACKAGE = "{{sdk.python.package}}"
SDK_MIN = "{{sdk.python.min}}"
SDK_MAX = "{{sdk.python.max}}"

_PAGE = 256
_BATCH = 100
_DIGITS = 6
_META = "metadatas"
_DOCS = "documents"
_EMBEDDINGS = "embeddings"


class UnsupportedFeature(NotImplementedError):
    pass


def _version_tuple(text: str) -> tuple[int, ...]:
    parts = []
    for token in re.split(r"[.+\-]", text.lstrip("v")):
        if not token.isdigit():
            break
        parts.append(int(token))
    return tuple(parts)


def requirement() -> str:
    return f"{SDK_PACKAGE}>={SDK_MIN},<{SDK_MAX}"


def check_sdk() -> str:
    try:
        installed = version(SDK_PACKAGE)
    except PackageNotFoundError as error:
        raise ImportError(f"{SDK_PACKAGE} is not installed; install '{requirement()}'") from error
    if not _version_tuple(SDK_MIN) <= _version_tuple(installed) < _version_tuple(SDK_MAX):
        raise ImportError(f"{SDK_PACKAGE} {installed} is not supported; install '{requirement()}'")
    return installed


check_sdk()

import chromadb  # noqa: E402
from chromadb.api import AdminAPI, ClientAPI  # noqa: E402
from chromadb.config import Settings  # noqa: E402


def unsupported(vendor: str, feature: str) -> NoReturn:
    raise UnsupportedFeature(f"{feature} is not supported for target {vendor}")


def env(name: str) -> str:
    value = os.environ.get(name)
    if value is None:
        raise KeyError(f"environment variable {name} is not set")
    return value


class Client:
    """The server endpoint, its tenant and default database, and one SDK client per database the program uses."""

    def __init__(self, uri: str, tenant: str, database: str) -> None:
        parsed = urlparse(uri)
        self.host = parsed.hostname or "localhost"
        self.ssl = parsed.scheme == "https"
        self.port = parsed.port or (443 if self.ssl else 8000)
        self.tenant = tenant
        self.database = database
        self._clients: dict[str, ClientAPI] = {}
        self._admin: AdminAPI | None = None

    def db(self, database: str | None = None) -> ClientAPI:
        name = database or self.database
        if name not in self._clients:
            self._clients[name] = chromadb.HttpClient(host=self.host, port=self.port, ssl=self.ssl, tenant=self.tenant,
                                                      database=name)
        return self._clients[name]

    def admin(self) -> AdminAPI:
        if self._admin is None:
            self._admin = chromadb.AdminClient(Settings(chroma_api_impl="chromadb.api.fastapi.FastAPI",
                                                        chroma_server_host=self.host, chroma_server_http_port=self.port,
                                                        chroma_server_ssl_enabled=self.ssl))
        return self._admin

    def close(self) -> None:
        self._clients.clear()
        self._admin = None


def connect(uri: str, tenant: str = "default_tenant", database: str = "default_database") -> Client:
    return Client(uri, tenant, database)


def record_id(key: Any) -> str:
    """Chroma id of a primary key: the key's text; integral floats count as integers."""
    if isinstance(key, bool) or not isinstance(key, (int, float, str)):
        raise TypeError(f"cannot use {key!r} as a Chroma primary key")
    if isinstance(key, float):
        if not key.is_integer():
            raise TypeError(f"cannot use {key!r} as a Chroma primary key")
        key = int(key)
    return str(key)


def _value(value: Any) -> Any:
    """Result values in one form for every host language: floats rounded, integral floats as integers."""
    if isinstance(value, float):
        rounded = round(value, _DIGITS)
        return int(rounded) if rounded.is_integer() else rounded
    if isinstance(value, (list, tuple)):
        return [_value(item) for item in value]
    if hasattr(value, "tolist"):
        return _value(value.tolist())
    if isinstance(value, dict):
        return {key: _value(item) for key, item in value.items()}
    return value


def _chunks(items: Sequence[Any], size: int) -> Iterator[Sequence[Any]]:
    for start in range(0, len(items), size):
        yield items[start:start + size]


def _collection(client: Client, collection: dict[str, Any]) -> Any:
    return client.db(collection.get("database")).get_collection(collection["name"], embedding_function=None)


def _filter(filter: dict[str, Any] | None) -> dict[str, Any]:
    """Chroma's where and where_document parts of a filter."""
    filter = filter or {}
    return {"where": filter.get("where"), "where_document": filter.get("where_document")}


# ---------------------------------------------------------------- databases and collections

def has_database(client: Client, name: str) -> bool:
    return any(database["name"] == name for database in client.admin().list_databases(tenant=client.tenant))


def create_database(client: Client, name: str) -> None:
    client.admin().create_database(name, tenant=client.tenant)


def drop_database(client: Client, name: str) -> None:
    client.admin().delete_database(name, tenant=client.tenant)
    client._clients.pop(name, None)


def has_collection(client: Client, name: str, database: str | None = None) -> bool:
    return any(item.name == name for item in _all_collections(client, database))


def _all_collections(client: Client, database: str | None) -> list[Any]:
    found: list[Any] = []
    while True:
        page = client.db(database).list_collections(limit=_PAGE, offset=len(found))
        found.extend(page)
        if len(page) < _PAGE:
            return found


def create_collection(client: Client, name: str, metric: str, database: str | None = None, hnsw: dict[str, Any] | None = None,
                      metadata: dict[str, Any] | None = None) -> None:
    """A collection whose embeddings the program supplies: no embedding function, the HNSW space and parameters given."""
    configuration: dict[str, Any] = {"hnsw": {"space": metric, **(hnsw or {})}}
    client.db(database).create_collection(name, configuration=configuration, metadata=_collection_metadata(metadata),
                                          embedding_function=None)


def _collection_metadata(metadata: dict[str, Any] | None) -> dict[str, Any] | None:
    """Collection metadata; tags are kept as JSON text, because the server rejects array values there."""
    if not metadata:
        return None
    return {key: json.dumps(value) if key == "tags" else value for key, value in metadata.items()}


def drop_collection(client: Client, name: str, database: str | None = None) -> None:
    client.db(database).delete_collection(name)


def require_collection(client: Client, name: str, database: str | None = None) -> None:
    """The collection must exist; Chroma serves every collection and its metadata is schemaless."""
    client.db(database).get_collection(name, embedding_function=None)


def rename_collection(client: Client, name: str, new_name: str, database: str | None = None) -> None:
    client.db(database).get_collection(name, embedding_function=None).modify(name=new_name)


def alter_collection(client: Client, name: str, database: str | None = None, hnsw: dict[str, Any] | None = None,
                     metadata: dict[str, Any] | None = None) -> None:
    """Mutable HNSW parameters, and collection metadata merged into the stored metadata (modify replaces it)."""
    handle = client.db(database).get_collection(name, embedding_function=None)
    if hnsw:
        handle.modify(configuration={"hnsw": hnsw})
    if metadata:
        merged = {**(handle.metadata or {}), **(_collection_metadata(metadata) or {})}
        handle.modify(metadata=merged)


def describe(client: Client, name: str, database: str | None = None, stats: bool = False,
             index_progress: bool = False) -> dict[str, Any]:
    """Name, metadata and HNSW settings; the local server indexes every write before it answers, so progress is always ready."""
    handle = client.db(database).get_collection(name, embedding_function=None)
    hnsw = (handle.configuration_json or {}).get("hnsw") or {}
    metadata = {key: json.loads(value) if key == "tags" else value for key, value in (handle.metadata or {}).items()}
    result: dict[str, Any] = {"name": handle.name, "database": database or client.database, "metadata": metadata,
                              "hnsw": {key: _value(hnsw[key]) for key in sorted(hnsw)}}
    if stats:
        result["count"] = handle.count()
    if index_progress:
        result["index_progress"] = "ready"
    return result


def await_index(client: Client, name: str, database: str | None = None) -> str:
    require_collection(client, name, database)
    return "ready"


def list_objects(client: Client, kind: str, scope: dict[str, Any] | None = None, key: str | None = None,
                 prefix: str | None = None, limit: int | None = None) -> list[str]:
    """Names of databases, collections, or the tenant or namespace values of a collection's slice key, sorted."""
    if kind == "databases":
        names = [database["name"] for database in client.admin().list_databases(tenant=client.tenant)]
    elif kind == "collections":
        names = [item.name for item in _all_collections(client, (scope or {}).get("database"))]
    else:
        assert scope is not None and key is not None
        names = sorted({str(row[key]) for row in _rows(client, scope, None, [key]) if row.get(key) is not None})
    names = sorted(name for name in names if prefix is None or name.startswith(prefix))
    return names if limit is None else names[:limit]


def clone_collection(client: Client, collection: dict[str, Any], target: str) -> dict[str, int]:
    """A new collection with the source's configuration and metadata, filled with a copy of every record."""
    source = _collection(client, collection)
    hnsw = {key: value for key, value in ((source.configuration_json or {}).get("hnsw") or {}).items()
            if key in ("ef_construction", "ef_search", "max_neighbors")}
    space = ((source.configuration_json or {}).get("hnsw") or {}).get("space", "l2")
    copy = client.db(collection.get("database")).create_collection(
        target, configuration={"hnsw": {"space": space, **hnsw}}, metadata=source.metadata or None, embedding_function=None)
    copied = 0
    for page in _pages(source, None, [_META, _DOCS, _EMBEDDINGS]):
        copy.add(ids=page["ids"], embeddings=page["embeddings"], metadatas=page["metadatas"],
                 documents=page["documents"] if any(doc is not None for doc in page["documents"]) else None)
        copied += len(page["ids"])
    return {"copied": copied}


# ---------------------------------------------------------------- records

def _check(collection: dict[str, Any], record: dict[str, Any]) -> None:
    for field, limit in collection.get("limits", {}).items():
        value = record.get(field)
        if value is None:
            continue
        if "max_items" in limit and len(value) > limit["max_items"]:
            raise ValueError(f"{field} has {len(value)} items; at most {limit['max_items']} are allowed")
        if "max_length" in limit:
            for text in value if isinstance(value, list) else [value]:
                if isinstance(text, str) and len(text) > limit["max_length"]:
                    raise ValueError(f"{field} is longer than {limit['max_length']} characters")


def _typed(collection: dict[str, Any], name: str, value: Any) -> Any:
    """Integral floats of integer fields as integers, also inside arrays."""
    if name in collection.get("integers", ()):
        if isinstance(value, float) and value.is_integer():
            return int(value)
        if isinstance(value, list):
            return [int(item) if isinstance(item, float) and item.is_integer() else item for item in value]
    return value


def _entry(collection: dict[str, Any], row: dict[str, Any], slice: dict[str, Any] | None = None) -> tuple[str, list[float], dict[str, Any], str | None]:
    """Id, embedding, metadata and document of a record; null values and empty arrays are left out, as Chroma stores neither."""
    record = {**collection.get("defaults", {}), **row, **(slice or {})}
    key = record.get(collection["key"])
    if key is None:
        raise ValueError(f"record without primary key {collection['key']}: {row}")
    _check(collection, record)
    vector = record.get(collection["vector"])
    if vector is None:
        raise ValueError(f"record without vector {collection['vector']}: {row}")
    if collection.get("dim") is not None and len(vector) != collection["dim"]:
        raise ValueError(f"{collection['vector']} has {len(vector)} dimensions; {collection['dim']} are declared")
    document = record.get(collection["document"]) if collection.get("document") else None
    metadata = {name: _typed(collection, name, value) for name, value in record.items()
                if name not in (collection["vector"], collection.get("document")) and value is not None and value != []}
    return record_id(key), [float(x) for x in vector], metadata, document


def _add(handle: Any, entries: Sequence[tuple[str, list[float], dict[str, Any], str | None]], batch_size: int) -> None:
    for chunk in _chunks(list(entries), batch_size):
        documents = [entry[3] for entry in chunk]
        handle.add(ids=[entry[0] for entry in chunk], embeddings=[entry[1] for entry in chunk],
                   metadatas=[entry[2] for entry in chunk],
                   documents=documents if any(doc is not None for doc in documents) else None)


def _existing(handle: Any, ids: Sequence[str]) -> list[str]:
    found: set[str] = set()
    for chunk in _chunks(list(ids), _PAGE):
        found.update(handle.get(ids=list(chunk), include=[])["ids"])
    return [rid for rid in ids if rid in found]


def insert_rows(client: Client, collection: dict[str, Any], rows: Sequence[dict[str, Any]], on_conflict: str = "error",
                batch_size: int = _BATCH, slice: dict[str, Any] | None = None) -> dict[str, int]:
    """Chroma's add skips ids that exist, so conflicts are detected first: error raises, ignore skips them."""
    handle = _collection(client, collection)
    entries = [_entry(collection, row, slice) for row in rows]
    existing = set(_existing(handle, [entry[0] for entry in entries]))
    if existing and on_conflict == "error":
        raise ValueError(f"{len(existing)} records already exist in {collection['name']}")
    fresh = [entry for entry in entries if entry[0] not in existing]
    _add(handle, fresh, batch_size)
    return {"insert_count": len(fresh), "skipped": len(entries) - len(fresh)}


def upsert_rows(client: Client, collection: dict[str, Any], rows: Sequence[dict[str, Any]], batch_size: int = _BATCH,
                slice: dict[str, Any] | None = None) -> dict[str, int]:
    """Whole-record replacement: Chroma's upsert merges metadata, so existing records are deleted and added again."""
    handle = _collection(client, collection)
    entries = list({entry[0]: entry for entry in (_entry(collection, row, slice) for row in rows)}.values())
    for chunk in _chunks(_existing(handle, [entry[0] for entry in entries]), _PAGE):
        handle.delete(ids=list(chunk))
    _add(handle, entries, batch_size)
    return {"upsert_count": len(entries)}


def _pages(handle: Any, filter: dict[str, Any] | None, include: list[str], ids: Sequence[str] | None = None) -> Iterator[dict[str, Any]]:
    """Every record that matches a filter (and the ids, if given), page by page."""
    parts = _filter(filter)
    offset = 0
    while True:
        page = handle.get(ids=list(ids) if ids is not None else None, where=parts["where"],
                          where_document=parts["where_document"], limit=_PAGE, offset=offset, include=include)
        if not page["ids"]:
            return
        yield {"ids": page["ids"], "embeddings": page.get("embeddings"), "metadatas": page.get("metadatas"),
               "documents": page.get("documents")}
        if len(page["ids"]) < _PAGE:
            return
        offset += _PAGE


def _rows(client: Client, collection: dict[str, Any], filter: dict[str, Any] | None, output: Sequence[str],
          ids: Sequence[str] | None = None, vectors: bool = False) -> list[dict[str, Any]]:
    """Matching records as rows (key first, then the output fields, then the vector if asked), in primary key order."""
    handle = _collection(client, collection)
    include = [_META]
    if collection.get("document") in output:
        include.append(_DOCS)
    if vectors:
        include.append(_EMBEDDINGS)
    rows = []
    for page in _pages(handle, filter, include, ids):
        for index, rid in enumerate(page["ids"]):
            rows.append(_row(collection, page, index, output, vectors))
    return sorted(rows, key=lambda row: row[collection["key"]])


def _row(collection: dict[str, Any], page: dict[str, Any], index: int, output: Sequence[str], vectors: bool) -> dict[str, Any]:
    metadata = (page.get("metadatas") or [None] * (index + 1))[index] or {}
    row: dict[str, Any] = {collection["key"]: metadata.get(collection["key"])}
    for name in output:
        if name == collection.get("document"):
            row[name] = page["documents"][index]
        else:
            row[name] = _value(metadata.get(name))
    if vectors:
        row[collection["vector"]] = _value([float(x) for x in page["embeddings"][index]])
    return row


def _targets(handle: Any, ids: Sequence[Any] | None, filter: dict[str, Any] | None) -> list[str]:
    """Ids of the records a write selects: the given keys that exist and match the filter, or every match of the filter."""
    if ids:
        wanted = list(dict.fromkeys(record_id(key) for key in ids))
        if filter:
            matching = {rid for page in _pages(handle, filter, [], wanted) for rid in page["ids"]}
            return [rid for rid in wanted if rid in matching]
        return _existing(handle, wanted)
    if filter is not None:
        return [rid for page in _pages(handle, filter, []) for rid in page["ids"]]
    raise ValueError("the statement selects no records")


def update_rows(client: Client, collection: dict[str, Any], ids: Sequence[Any] | None = None,
                filter: dict[str, Any] | None = None, values: dict[str, Any] | None = None,
                rows: Sequence[dict[str, Any]] | None = None, remove: Sequence[str] = (), mode: str = "merge",
                append: Sequence[str] = (), remove_items: Sequence[str] = ()) -> dict[str, int]:
    """Chroma's update merges metadata and deletes the keys set to None; replace also clears the keys not given. A new
    document is sent with the stored embedding, because the SDKs would otherwise embed the document."""
    handle = _collection(client, collection)
    key = collection["key"]
    replacements = {record_id(row[key]): row for row in rows or []}
    if replacements:
        chosen = {record_id(item) for item in ids or ()}
        targets = [rid for rid in _targets(handle, [row[key] for row in rows or []], filter) if not chosen or rid in chosen]
    elif ids or filter is not None:
        targets = _targets(handle, ids, filter)
    else:
        raise ValueError("update requires ids, a filter or records")
    if not targets:
        return {"update_count": 0}
    document = collection.get("document")
    redocument = bool(document) and (document in (values or {}) or any(document in row for row in rows or []))
    stored: dict[str, dict[str, Any]] = {}
    embeddings: dict[str, list[float]] = {}
    for page in _pages(handle, None, [_META, _EMBEDDINGS] if redocument else [_META], targets):
        for index, rid in enumerate(page["ids"]):
            stored[rid] = page["metadatas"][index] or {}
            if redocument:
                embeddings[rid] = [float(x) for x in page["embeddings"][index]]
    for rid in targets:
        record = {**replacements.get(rid, {}), **(values or {})}
        if key in record and record_id(record[key]) != rid:
            raise ValueError(f"update cannot change the primary key {key}")
        current = stored.get(rid, {})
        metadata: dict[str, Any] = {}
        for name, value in record.items():
            if name in (collection["vector"], collection.get("document"), key):
                continue
            if name in append:
                value = list(current.get(name) or []) + [_typed(collection, name, item) for item in value or []]
            elif name in remove_items:
                dropped = [_typed(collection, name, item) for item in value or []]
                value = [item for item in current.get(name) or [] if item not in dropped]
            metadata[name] = None if value == [] else _typed(collection, name, value)
        for name in remove:
            metadata[name] = None
        if mode == "replace":
            for name in current:
                if name != key and name not in metadata:
                    metadata[name] = None
        _check(collection, metadata)
        options: dict[str, Any] = {"ids": [rid]}
        if metadata:
            options["metadatas"] = [metadata]
        if record.get(collection["vector"]) is not None:
            options["embeddings"] = [[float(x) for x in record[collection["vector"]]]]
        if document and document in record:
            options["documents"] = [record[document]]
            options.setdefault("embeddings", [embeddings[rid]])
        if len(options) > 1:
            handle.update(**options)
    return {"update_count": len(targets)}


def delete_rows(client: Client, collection: dict[str, Any], ids: Sequence[Any] | None = None,
                filter: dict[str, Any] | None = None, delete_all: bool = False, limit: int | None = None) -> dict[str, int]:
    """Deletes by id after resolving the targets, so the count is exact; limit takes the first targets in key order."""
    handle = _collection(client, collection)
    if delete_all and not ids:
        targets = [rid for page in _pages(handle, filter, []) for rid in page["ids"]]
    else:
        targets = _targets(handle, ids, filter if filter is not None or ids else {})
    if limit is not None:
        keyed = sorted((meta.get(collection["key"]), rid) for page in _pages(handle, None, [_META], targets)
                       for rid, meta in zip(page["ids"], page["metadatas"]))
        targets = [rid for _, rid in keyed[:limit]]
    for chunk in _chunks(targets, _PAGE):
        handle.delete(ids=list(chunk))
    return {"delete_count": len(targets)}


def fill_field(client: Client, collection: dict[str, Any], field: str, value: Any) -> dict[str, int]:
    """Writes a new field's default into every record that lacks it."""
    handle = _collection(client, collection)
    targets = [rid for page in _pages(handle, None, [_META]) for rid, meta in zip(page["ids"], page["metadatas"])
               if (meta or {}).get(field) is None]
    for chunk in _chunks(targets, _PAGE):
        handle.update(ids=list(chunk), metadatas=[{field: _typed(collection, field, value)} for _ in chunk])
    return {"update_count": len(targets)}


def drop_field(client: Client, collection: dict[str, Any], field: str) -> dict[str, int]:
    """Removes a metadata key from every record (Chroma deletes a key set to None)."""
    handle = _collection(client, collection)
    targets = [rid for page in _pages(handle, None, [_META]) for rid, meta in zip(page["ids"], page["metadatas"])
               if field in (meta or {})]
    for chunk in _chunks(targets, _PAGE):
        handle.update(ids=list(chunk), metadatas=[{field: None} for _ in chunk])
    return {"update_count": len(targets)}


def rename_field(client: Client, collection: dict[str, Any], field: str, new_name: str) -> dict[str, int]:
    """Moves a metadata key to a new name in every record that has it."""
    handle = _collection(client, collection)
    changed = 0
    for page in _pages(handle, None, [_META]):
        for rid, meta in zip(page["ids"], page["metadatas"]):
            if field in (meta or {}):
                handle.update(ids=[rid], metadatas=[{new_name: meta[field], field: None}])
                changed += 1
    return {"update_count": changed}


def read_records(client: Client, location: str) -> list[dict[str, Any]]:
    """Records of a local JSON array or JSON Lines file (file:// URI or path)."""
    path = location[len("file://"):] if location.startswith("file://") else location
    with open(path, encoding="utf-8") as handle:
        text = handle.read()
    stripped = text.lstrip()
    if stripped.startswith("["):
        return list(json.loads(stripped))
    return [json.loads(line) for line in text.splitlines() if line.strip()]


def import_file(client: Client, collection: dict[str, Any], location: str, on_conflict: str | None = None,
                batch_size: int = _BATCH, slice: dict[str, Any] | None = None) -> dict[str, int]:
    rows = read_records(client, location)
    if on_conflict in ("update", "replace"):
        return upsert_rows(client, collection, rows, batch_size, slice)
    return insert_rows(client, collection, rows, on_conflict or "error", batch_size, slice)


# ---------------------------------------------------------------- reads

def get_rows(client: Client, collection: dict[str, Any], ids: Sequence[Any], output: Sequence[str],
             filter: dict[str, Any] | None = None, vectors: bool = False) -> list[dict[str, Any]]:
    """Records by primary key, in the order of the keys given."""
    wanted = list(dict.fromkeys(record_id(key) for key in ids))
    found = {record_id(row[collection["key"]]): row for row in _rows(client, collection, filter, output, wanted, vectors)}
    return [found[rid] for rid in wanted if rid in found]


def count(client: Client, collection: dict[str, Any], filter: dict[str, Any] | None = None) -> int:
    handle = _collection(client, collection)
    if not filter:
        return handle.count()
    return sum(len(page["ids"]) for page in _pages(handle, filter, []))


def scroll(client: Client, collection: dict[str, Any], output: Sequence[str], filter: dict[str, Any] | None = None,
           limit: int | None = None, offset: int | None = None, order: Sequence[dict[str, Any]] = (),
           vectors: bool = False) -> list[dict[str, Any]]:
    """Records in primary key order, or in the order of the sort fields; Chroma returns them in insertion order."""
    fields = list(dict.fromkeys([*output, *(item["key"] for item in order if item["key"] != collection["key"])]))
    rows = _rows(client, collection, filter, fields, None, vectors)
    for item in reversed(order):
        rows.sort(key=lambda row: (row.get(item["key"]) is None, row.get(item["key"])), reverse=item.get("direction") == "desc")
    rows = rows[offset or 0:]
    if limit is not None:
        rows = rows[:limit]
    return [{name: row.get(name) for name in [collection["key"], *output, *([collection["vector"]] if vectors else [])]} for row in rows]


def sample_rows(client: Client, collection: dict[str, Any], size: int, output: Sequence[str], first: bool = False,
                filter: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    """A random sample (or the first records in key order) of the matching records."""
    rows = _rows(client, collection, filter, output)
    if first:
        return rows[:size]
    return sorted(random.sample(rows, min(size, len(rows))), key=lambda row: row[collection["key"]])


def similarity(metric: str, distance: float) -> float:
    """Canonical similarity of a Chroma distance: l2 is squared Euclidean, cosine and ip are 1 minus the similarity."""
    if metric == "l2":
        return -math.sqrt(max(distance, 0.0))
    return 1.0 - distance


def lookup_vector(client: Client, collection: dict[str, Any], id: Any) -> list[float]:
    found = _collection(client, collection).get(ids=[record_id(id)], include=[_EMBEDDINGS])
    if not found["ids"]:
        raise KeyError(f"record {id!r} not found in {collection['name']}")
    return [float(x) for x in found["embeddings"][0]]


def _within(score: float, score_min: float | None, score_max: float | None) -> bool:
    return (score_min is None or score >= score_min) and (score_max is None or score <= score_max)


def _nearest(handle: Any, collection: dict[str, Any], vector: Sequence[float], size: int, filter: dict[str, Any] | None,
             output: Sequence[str], vectors: bool, native: bool) -> list[tuple[dict[str, Any], float]]:
    """Nearest records with their canonical similarity, or Chroma's own distance with native."""
    include = [_META, "distances"]
    if collection.get("document") in output:
        include.append(_DOCS)
    if vectors:
        include.append(_EMBEDDINGS)
    parts = _filter(filter)
    result = handle.query(query_embeddings=[[float(x) for x in vector]], n_results=size, where=parts["where"],
                          where_document=parts["where_document"], include=include)
    page = {name: (result.get(name) or [None])[0] for name in ("ids", "embeddings", "metadatas", "documents", "distances")}
    hits = []
    for index in range(len(page["ids"] or [])):
        row = _row(collection, page, index, output, vectors)
        distance = float(page["distances"][index])
        hits.append((row, distance if native else similarity(collection["metric"], distance)))
    return hits


def _hits(collection: dict[str, Any], hits: Sequence[tuple[dict[str, Any], float]], offset: int | None, limit: int,
          score_min: float | None, score_max: float | None, native: bool) -> list[dict[str, Any]]:
    ranked = sorted(hits, key=lambda hit: hit[1] if native else -hit[1])[offset or 0:(offset or 0) + limit]
    result = []
    for row, score in ranked:
        if _within(score, score_min, score_max):
            row = dict(row)
            result.append({"id": row.pop(collection["key"]), "score": _value(score), **row})
    return result


def vector_search(client: Client, collection: dict[str, Any], vector: Sequence[float], limit: int, output: Sequence[str],
                  filter: dict[str, Any] | None = None, offset: int | None = None, score_min: float | None = None,
                  score_max: float | None = None, native: bool = False, vectors: bool = False) -> list[dict[str, Any]]:
    """Nearest neighbours by the collection's HNSW space; offset pages the ranking, bounds apply to the returned score."""
    handle = _collection(client, collection)
    hits = _nearest(handle, collection, vector, limit + (offset or 0), filter, output, vectors, native)
    return _hits(collection, hits, offset, limit, score_min, score_max, native)


def recommend(client: Client, collection: dict[str, Any], positives: Sequence[Any], limit: int, output: Sequence[str],
              negatives: Sequence[Any] = (), lookup: dict[str, Any] | None = None, filter: dict[str, Any] | None = None,
              offset: int | None = None, score_min: float | None = None, score_max: float | None = None,
              native: bool = False, vectors: bool = False) -> list[dict[str, Any]]:
    """The average-vector strategy, avg(positive) + (avg(positive) - avg(negative)); example records are not returned."""
    source = lookup or collection

    def example(item: Any) -> list[float]:
        return [float(x) for x in item] if isinstance(item, (list, tuple)) else lookup_vector(client, source, item)

    good = [example(item) for item in positives]
    bad = [example(item) for item in negatives]
    mean = [sum(column) / len(good) for column in zip(*good)]
    query = [2 * p - n for p, n in zip(mean, [sum(column) / len(bad) for column in zip(*bad)])] if bad else mean
    excluded = {record_id(item) for item in [*positives, *negatives]
                if not isinstance(item, (list, tuple)) and source["name"] == collection["name"]}
    handle = _collection(client, collection)
    hits = _nearest(handle, collection, query, limit + (offset or 0) + len(excluded), filter, output, vectors, native)
    hits = [hit for hit in hits if record_id(hit[0][collection["key"]]) not in excluded]
    return _hits(collection, hits, offset, limit, score_min, score_max, native)


def distance_matrix(client: Client, collection: dict[str, Any], sample: int = 10, limit: int = 3,
                    filter: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    """A random sample of the matching records, each paired with its nearest neighbours within the sample (as Qdrant's
    distance matrix), with primary keys and canonical similarities, sorted by key."""
    handle = _collection(client, collection)
    records = [(meta[collection["key"]], rid, [float(x) for x in vector]) for page in _pages(handle, filter, [_META, _EMBEDDINGS])
               for rid, meta, vector in zip(page["ids"], page["metadatas"], page["embeddings"])]
    picked = random.sample(records, min(sample, len(records)))
    ids = [rid for _, rid, _ in picked]
    pairs = []
    for key, rid, vector in picked:
        result = handle.query(query_embeddings=[vector], n_results=min(limit + 1, len(ids)), ids=ids, include=[_META, "distances"])
        neighbours = [(meta[collection["key"]], float(distance)) for other, meta, distance
                      in zip(result["ids"][0], result["metadatas"][0], result["distances"][0]) if other != rid]
        for other_key, distance in neighbours[:limit]:
            pairs.append({"a": key, "b": other_key, "score": _value(similarity(collection["metric"], distance))})
    return sorted(pairs, key=lambda pair: (pair["a"], pair["b"]))
